export function getCityJournalPosts(citySlug: string): CityJournalPost[] {
  if (!targetCitySlugs.has(citySlug)) return [];
  const posts = cityJournalPosts.filter((post) => post.citySlug === citySlug);
  if (posts.length < 3) {
    throw new Error(`Expected at least three city Journal posts for "${citySlug}", found ${posts.length}`);
  }
  return posts;
}
